"""Generate Arabic map-caption constants independently of Android UI resources."""
import argparse
import json
from pathlib import Path


def render(captions):
    lines = [
        '// Generated by tools/mukshat/generate_map_caption_labels.py; do not edit.',
        '#pragma once', '', '#include <string_view>', '', 'namespace df::mukshat', '{',
        'inline constexpr std::string_view ArabicMapCaptionForType(std::string_view type)', '{',
    ]
    for key, text in captions.items():
        lines += [f'  if (type == {json.dumps(key)})', f'    return {json.dumps(text, ensure_ascii=False)};']
    lines += ['  return {};', '}', '}  // namespace df::mukshat', '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[2]
    source = root/'data/strings/mukshat_map_captions.json'
    record = json.loads(source.read_text())
    assert record['locale'] == 'ar'
    generated = render(record['captions'])
    target = root/'libs/drape_frontend/mukshat_map_caption_labels.hpp'
    if args.check:
        assert target.read_text() == generated
    else:
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(generated)
    print(json.dumps({'passed': True, 'locale': 'ar', 'caption_keys': len(record['captions']),
                      'check_only': args.check}))


if __name__ == '__main__':
    main()
